parameters.jsCode:
const normalizeText = (value) => {
  if (typeof value !== 'string') return '';
  return value.trim().replace(/\s+/g,' ')
};
const email = normalizeText($json.requester?.email).toLowerCase();
const subject = normalizeText($json.subject);
const priority = normalizeText($json.priority).toLowerCase();
return {
  json: {
    ...$json,
    normalized_email: email,
    normalized_subject: subject,
    normalized_priority: priority,
    has_required_information: email !== '' && subject !== ''
  }
};
